// ?W???`ÅÒ??p?????G?????????s??????Åf?Åg_?V?F?[?_?[???R?Åg?p?C?????s??
static int CreateD3D11BaseSimpleVertexShader( int InputLayout )
{
	D_D3DXMACRO Macro[ 5 ] ;
	int MacroNum = 0 ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( GD3D11.Device.Shader.Base.BaseSimple_VS[ InputLayout ] != NULL )
	{
		return 0 ;
	}

	if( InputLayout == D3D11_VERTEX_INPUTLAYOUT_SHADER_2D )
	{
		Macro[ MacroNum ].Name = NULL ;
		Macro[ MacroNum ].Definition = NULL ;
		MacroNum ++ ;

		return Graphics_D3D11_CompileVertexShader( "Base_2D_VS.hlsl", "VS_Shader2D", Macro, &GD3D11.Device.Shader.Base.BaseSimple_VS[ InputLayout ], &GD3D11.ShaderCode.Base.BaseSimple_VS_Blob[ InputLayout ] ) ;
	}
	else
	if( InputLayout < D3D11_VERTEX_INPUTLAYOUT_NOTEX_3D )
	{
		Macro[ MacroNum ].Name = "USE_DIFFUSE" ;
		Macro[ MacroNum ].Definition = "" ;
		MacroNum ++ ;

		if( InputLayout >= D3D11_VERTEX_INPUTLAYOUT_2D )
		{
			Macro[ MacroNum ].Name = "USE_TEXCOORD0" ;
			Macro[ MacroNum ].Definition = "" ;
			MacroNum ++ ;
		}

		if( InputLayout == D3D11_VERTEX_INPUTLAYOUT_BLENDTEX_2D )
		{
			Macro[ MacroNum ].Name = "USE_SPECULAR" ;
			Macro[ MacroNum ].Definition = "" ;
			MacroNum ++ ;

			Macro[ MacroNum ].Name = "USE_TEXCOORD1" ;
			Macro[ MacroNum ].Definition = "" ;
			MacroNum ++ ;
		}

		Macro[ MacroNum ].Name = NULL ;
		Macro[ MacroNum ].Definition = NULL ;
		MacroNum ++ ;

		return Graphics_D3D11_CompileVertexShader( "Base_2D_VS.hlsl", "VS2D_Normal", Macro, &GD3D11.Device.Shader.Base.BaseSimple_VS[ InputLayout ], &GD3D11.ShaderCode.Base.BaseSimple_VS_Blob[ InputLayout ] ) ;
	}
	else
	{
		switch( InputLayout )
		{
		case D3D11_VERTEX_INPUTLAYOUT_NOTEX_3D :
			break ;

		case D3D11_VERTEX_INPUTLAYOUT_3D :
			Macro[ MacroNum ].Name = "USE_TEXCOORD0" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
			break ;

		case D3D11_VERTEX_INPUTLAYOUT_3D_LIGHT :
			Macro[ MacroNum ].Name = "USE_VERTEX3D" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
			break ;

		case D3D11_VERTEX_INPUTLAYOUT_SHADER_3D :
			Macro[ MacroNum ].Name = "USE_VERTEX3DSHADER" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
			break ;
		}

		Macro[ MacroNum ].Name = NULL ;
		Macro[ MacroNum ].Definition = NULL ;
		MacroNum ++ ;

		return Graphics_D3D11_CompileVertexShader( "Base_3D_Simple_VS.hlsl", "VS3D_Normal", Macro, &GD3D11.Device.Shader.Base.BaseSimple_VS[ InputLayout ], &GD3D11.ShaderCode.Base.BaseSimple_VS_Blob[ InputLayout ] ) ;
	}
}

