extern int CreateD3D11MV1VertexLightingVertexShader( int ShadowMap, int MeshType, int BumpMap, int FogType, int LightIndex )
{
	GRAPHICS_HARDDATA_DIRECT3D11_DEVICE           *Device = &GraphicsHardDataDirect3D11.Device ;
	GRAPHICS_HARDWARE_DIRECT3D11_SHADER           *Shader = &Device->Shader ;
	GRAPHICS_HARDWARE_DIRECT3D11_SHADER_MODEL     *SM     = &Shader->Model ;
	const BYTE *LightMode ;
	int i ;
	D_D3DXMACRO Macro[ 20 ] ;
	int MacroNum = 0 ;

	LightMode = GD3D11.ShaderCode.Base.LightIndex20LightMode[ LightIndex ] ;

	// ?????????????????Åˆ??ÅÒ?????????
	if( SM->MV1_VertexLighting_VS[ ShadowMap ][ MeshType ][ BumpMap ][ FogType ][ LightIndex ] != NULL )
	{
		return 0 ;
	}

	if( ShadowMap != 0 )
	{
		Macro[ MacroNum ].Name = "SHADOWMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	if( MeshType > 0 )
	{
		Macro[ MacroNum ].Name = "SKINMESH" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;

		if( MeshType == 2 )
		{
			Macro[ MacroNum ].Name = "BONE8" ;
			Macro[ MacroNum ].Definition = "1" ;
			MacroNum ++ ;
		}
	}

	if( BumpMap != 0 )
	{
		Macro[ MacroNum ].Name = "BUMPMAP" ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "PHONG" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	if( g_ShaderMacro_FogTypeName[ FogType ] != NULL )
	{
		Macro[ MacroNum ].Name = g_ShaderMacro_FogTypeName[ FogType ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = "USE_SPE" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	Macro[ MacroNum ].Name = "LG_USE" ;
	Macro[ MacroNum ].Definition = "1" ;
	MacroNum ++ ;

	for( i = 0 ; i < 3 ; i ++ )
	{
		if( LightMode[ i ] == 0 )
		{
			continue ;
		}

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Use[ i ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;

		Macro[ MacroNum ].Name = g_ShaderMacro_LG_Type[ i ][ LightMode[ i ] ] ;
		Macro[ MacroNum ].Definition = "1" ;
		MacroNum ++ ;
	}

	Macro[ MacroNum ].Name = NULL ;
	Macro[ MacroNum ].Definition = NULL ;
	MacroNum ++ ;

	return Graphics_D3D11_CompileVertexShader(
		"MV1Default_VertexLighting_VS.hlsl",
		"main",
		Macro,
		&SM->MV1_VertexLighting_VS[ ShadowMap ][ MeshType ][ BumpMap ][ FogType ][ LightIndex ],
		ShadowMap == 0 && FogType == 0 && LightIndex == 0 ? &GD3D11.ShaderCode.Base.MV1_VertexLighting_VS_Blob[ MeshType ][ BumpMap ] : NULL
	) ;
}

