	if( OWI->DXGIOutput != NULL )
	{
		Direct3D11_ObjectRelease( OWI->DXGIOutput ) ;
		OWI->DXGIOutput = NULL ;
	}

	if( OWI->DXGIOutput1 != NULL )
	{
		Direct3D11_ObjectRelease( OWI->DXGIOutput1 ) ;
		OWI->DXGIOutput1 = NULL ;
	}

	if( OWI->DXGIDuplicationTextureSRV != NULL )
	{
		Direct3D11_Release_ShaderResourceView( OWI->DXGIDuplicationTextureSRV ) ;
		OWI->DXGIDuplicationTextureSRV = NULL ;
	}

