// ?t???X?N???[?Åg??Åf????s??
extern int Graphics_D3D11_FullscreenSetup( int IsFullscreen )
{
	if( GD3D11.Device.Screen.OutputWindowInfo[ 0 ].DXGISwapChain == NULL ||
		GD3D11.Device.Screen.FullscreenSatte == IsFullscreen )
	{
		return 0 ;
	}

	if( IsFullscreen )
	{
		DXGISwapChain_SetFullscreenState( GD3D11.Device.Screen.OutputWindowInfo[ 0 ].DXGISwapChain, TRUE, GD3D11.Device.Screen.OutputWindowInfo[ 0 ].DXGIOutput ) ;
	}
	else
	{
		DXGISwapChain_SetFullscreenState( GD3D11.Device.Screen.OutputWindowInfo[ 0 ].DXGISwapChain, FALSE, NULL ) ;
	}

	GD3D11.Device.Screen.FullscreenSatte = IsFullscreen ;

	return 0 ;
}



















