		// ?????g????Åf????[Ågx?X?e?Åg?V???X?e?[?g???????????Åˆ???Å}?Å}???[Ågx?X?e?Åg?V???X?e?[?g??????????
		hr = D3D11Device_CreateDepthStencilState( &DepthStencilDesc, &GD3D11.Device.Shader.Base.StretchRect_DepthStencilState ) ;
