		// ?ÅÒ?C?g???pÅgx???????s?????????????????Z?b?g????
		Graphics_D3D11_DrawSetting_SetLightNoAngleAttenuation( GD3D11.Device.DrawSetting.NoLightAngleAttenuation ) ;

