// ?r?f?I?????????e????Åg???( 64bitÅh? )
extern	int		Graphics_Hardware_D3D11_GetVideoMemorySizeEx_PF( ULONGLONG *TotalSize, ULONGLONG *UseSize )
{
	D_DXGI_QUERY_VIDEO_MEMORY_INFO MemoryInfo ;
	D_DXGI_ADAPTER_DESC Desc ;

	if( DXGIAdapter3_QueryVideoMemoryInfo_Default( 0, D_DXGI_MEMORY_SEGMENT_GROUP_LOCAL, &MemoryInfo ) != S_OK )
	{
		return -1 ;
	}

	if( DXGIAdapter_GetDesc_Default( &Desc ) != S_OK )
	{
		return -1 ;
	}

	if( TotalSize != NULL )
	{
		*TotalSize = Desc.DedicatedVideoMemory ;
	}

	if( UseSize != NULL )
	{
		*UseSize = MemoryInfo.CurrentUsage ;
	}

	return 0 ;
}

