extern void *Graphics_Hardware_D3D11_GetDesktopScreenGraphMemImage_PF( int x1, int y1, int x2, int y2, int *Width, int *Height, int *Stride, int ColorBitDepth )
{
	GRAPHICS_HARDDATA_DIRECT3D11_OUTPUTWINDOWINFO *OWI ;
	D_ID3D11Texture2D *MapTempTexture = NULL ;
	RECT Rect ;
	RECT SrcRect ;
	int CaptureW, CaptureH ;
	int BufferStride ;
	COLORDATA DestColorData ;
	RECT DesktopRect ;
	int RectW ;
	int RectH ;

	// Åg]Åe??????J?ÅÒ?[?f?[?^??????
	if( ColorBitDepth == 24 )
	{
		CreateFullColorData( &DestColorData ) ;
	}
	else
	{
		CreateARGB8ColorData( &DestColorData ) ;
	}

	DesktopRect.left = WinAPIData.Win32Func.GetSystemMetricsFunc( SM_XVIRTUALSCREEN ) ;
	DesktopRect.top  = WinAPIData.Win32Func.GetSystemMetricsFunc( SM_YVIRTUALSCREEN ) ;

	RectW = WinAPIData.Win32Func.GetSystemMetricsFunc( SM_CXVIRTUALSCREEN ) ;
	RectH = WinAPIData.Win32Func.GetSystemMetricsFunc( SM_CYVIRTUALSCREEN ) ;

	DesktopRect.right  = DesktopRect.left + RectW ;
	DesktopRect.bottom = DesktopRect.top  + RectH ;

	// ?wÅf??????`??????
	if( x1 < DesktopRect.left )
	{
		x1 = DesktopRect.left ;
	}
	if( y1 < DesktopRect.top )
	{
		y1 = DesktopRect.top ;
	}
	if( x2 > DesktopRect.right )
	{
		x2 = DesktopRect.right ;
	}
	if( y2 > DesktopRect.bottom )
	{
		y2 = DesktopRect.bottom ;
	}

	// ???????????v?Z
	CaptureW = x2 - x1 ;
	CaptureH = y2 - y1 ;

	// ?o?????E?C?Åg?h?E??????????Åg??????ÅN??
	OWI = &GD3D11.Device.Screen.OutputWindowInfo[ GD3D11.Device.Screen.TargetOutputWindow ] ;

	// ?o?????E?B?Åg?h?E????????????????????ÅÒ????????I??
	if( WinAPIData.Win32Func.IsWindowFunc( OWI->TargetWindow ) == FALSE )
	{
		return 0 ;
	}

	// DXGIOutputDuplication ????Åh?
	if( Graphics_D3D11_SetupDuplicationOutputTexture() < 0 )
	{
		return NULL ;
	}

	// 1?ÅÒ?C?Åg???o?C?g?Åh???Z?o
	BufferStride = ColorBitDepth * CaptureW / 8 ;
	BufferStride = ( BufferStride + 3 ) / 4 * 4 ;

	if( WinData.DXGIDesktopImageAddress == NULL ||
		CaptureW != WinData.DXGIDesktopImageWidth ||
		CaptureH != WinData.DXGIDesktopImageHeight )
	{
		if( WinData.DXGIDesktopImageAddress != NULL )
		{
			DXFREE( WinData.DXGIDesktopImageAddress ) ;
			WinData.DXGIDesktopImageAddress = NULL ;
		}
		WinData.DXGIDesktopImageAddress = DXALLOC( BufferStride * CaptureH * ColorBitDepth / 8 ) ;
		WinData.DXGIDesktopImageWidth = CaptureW ;
		WinData.DXGIDesktopImageHeight = CaptureH ;
	}

	// ?}?b?v??????
	{
		BASEIMAGE BaseImage ;
		POINT DestPoint ;

		// ?e?N?X?`?????}?b?v
		SrcRect.left   = x1 ;
		SrcRect.top    = y1 ;
		SrcRect.right  = x2 ;
		SrcRect.bottom = y2 ;
		if( Graphics_D3D11_Texture2D_Map(
				OWI->DXGIDuplicationTexture2D,
				NULL,
				0,
				0,
				&SrcRect,
				&BaseImage,
				&MapTempTexture ) < 0 )
		{
			goto ERR ;
		}

		// ?C???[?W??Åg]Åe?
		DestPoint.x = 0 ;
		DestPoint.y = 0 ;
		Rect.left   = 0 ;
		Rect.top    = 0 ;
		Rect.right  = BaseImage.Width ;
		Rect.bottom = BaseImage.Height ;
		NS_GraphColorMatchBltVer2(
			WinData.DXGIDesktopImageAddress, BufferStride, &DestColorData,
			BaseImage.GraphData, BaseImage.Pitch, &BaseImage.ColorData,
			NULL, 0, NULL,
			DestPoint, &SrcRect,
			FALSE, FALSE, 0, FALSE, FALSE, FALSE, FALSE, FALSE
		) ;
	}

	// ?f?X?N?g?b?v?C???[?W????????Åe?Åg?
	if( Width != NULL )
	{
		*Width = CaptureW ;
	}

	if( Height != NULL )
	{
		*Height = CaptureH ;
	}

	if( Stride != NULL )
	{
		*Stride = BufferStride ;
	}

	if( MapTempTexture != NULL )
	{
		Graphics_D3D11_Texture2D_Unmap( MapTempTexture ) ;
		MapTempTexture = NULL ;
	}

	// ?????I??
	return WinData.DXGIDesktopImageAddress ;

ERR :
	if( MapTempTexture != NULL )
	{
		Graphics_D3D11_Texture2D_Unmap( MapTempTexture ) ;
		MapTempTexture = NULL ;
	}

	return NULL ;
}

