// ?V?F?[?_?[?n?Åg?h?????ÅÒ??ÅÒ?????
extern	int		Graphics_Hardware_D3D11_Shader_Create_PF( int ShaderHandle, int ShaderType, void *Image, int ImageSize, int ImageAfterFree, int ASyncThread )
{
	SHADERHANDLEDATA       *pShader ;
	D_ID3D11VertexShader   *VertexShader   = NULL ;
	D_ID3D11GeometryShader *GeometryShader = NULL ;
	D_ID3D11PixelShader    *PixelShader    = NULL ;

	// ?G?ÅÒ?[Åh?Åf?
	if( ASyncThread )
	{
		if( SHADERCHK_ASYNC( ShaderHandle, pShader ) )
			return -1 ;
	}
	else
	{
		if( SHADERCHK( ShaderHandle, pShader ) )
			return -1 ;
	}

	// ?V?F?[?_?[??????????
	switch( ShaderType )
	{
	case DX_SHADERTYPE_VERTEX :
		if( D3D11Device_CreateVertexShader_ASync( Image, ( SIZE_T )ImageSize, NULL, &VertexShader, ASyncThread ) != S_OK )
		{
			DXST_LOGFILE_ADDUTF16LE( "\x02\x98\xb9\x70\xb7\x30\xa7\x30\xfc\x30\xc0\x30\xfc\x30\x6e\x30\x5c\x4f\x10\x62\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x0a\x00\x00"/*@ L"Åf?Åg_?V?F?[?_?[??????????Åhs????????\n" @*/ ) ;
			goto ERR ;
		}
		break ;

	case DX_SHADERTYPE_GEOMETRY :
		if( D3D11Device_CreateGeometryShader_ASync( Image, ( SIZE_T )ImageSize, NULL, &GeometryShader, ASyncThread ) != S_OK )
		{
			DXST_LOGFILE_ADDUTF16LE( "\xb8\x30\xaa\x30\xe1\x30\xc8\x30\xea\x30\xb7\x30\xa7\x30\xfc\x30\xc0\x30\xfc\x30\x6e\x30\x5c\x4f\x10\x62\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x0a\x00\x00"/*@ L"?W?I???g???V?F?[?_?[??????????Åhs????????\n" @*/ ) ;
			goto ERR ;
		}
		break ;

	case DX_SHADERTYPE_PIXEL :
		if( D3D11Device_CreatePixelShader_ASync( Image, ( SIZE_T )ImageSize, NULL, &PixelShader, ASyncThread ) != S_OK )
		{
			DXST_LOGFILE_ADDUTF16LE( "\xd4\x30\xaf\x30\xbb\x30\xeb\x30\xb7\x30\xa7\x30\xfc\x30\xc0\x30\xfc\x30\x6e\x30\x5c\x4f\x10\x62\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x0a\x00\x00"/*@ L"?s?N?Z???V?F?[?_?[??????????Åhs????????\n" @*/ ) ;
			goto ERR ;
		}
		break ;
	}

	// ?o?C?i???C???[?W????ÅeÅ˜?????????????????m??
	pShader->FunctionCode = DXCALLOC( ( size_t )ImageSize ) ;
	if( pShader->FunctionCode == NULL )
	{
		DXST_LOGFILE_ADDUTF16LE( "\xe1\x30\xe2\x30\xea\x30\x6e\x30\xba\x78\xdd\x4f\x6b\x30\x31\x59\x57\x65\x57\x30\x7e\x30\x57\x30\x5f\x30\x00"/*@ L"?????????m??????Åhs????????" @*/ ) ;
		goto ERR ;
	}

	// ?o?C?i???C???[?W????ÅeÅ˜????
	_MEMCPY( pShader->FunctionCode, Image, ( size_t )ImageSize ) ;

	// ?o?C?i???C???[?W???T?C?Y????ÅeÅ˜????
	pShader->FunctionCodeSize = ImageSize ;

	// ?V?F?[?_?[?^?C?v????ÅeÅ˜????
	pShader->ShaderType = ShaderType ;

	// ?V?F?[?_?[???A?h???X????ÅeÅ˜
	switch( ShaderType )
	{
	case DX_SHADERTYPE_VERTEX :
		pShader->PF->D3D11.VertexShader = VertexShader ;
		break ;

	case DX_SHADERTYPE_GEOMETRY :
		pShader->PF->D3D11.GeometryShader = GeometryShader ;
		break ;

	case DX_SHADERTYPE_PIXEL :
		pShader->PF->D3D11.PixelShader = PixelShader ;
		break ;
	}

	// ????????ÅÒ??????Å~?????t?ÅÒ?O???Åò??????????ÅÒ???????
	if( ImageAfterFree )
	{
		DXFREE( Image ) ;
	}

	// ?????I??
	return 0 ;

ERR :
	if( VertexShader )
	{
		Direct3D11_Release_VertexShader_ASync( VertexShader, ASyncThread ) ;
	}

	if( PixelShader )
	{
		Direct3D11_Release_PixelShader_ASync( PixelShader, ASyncThread ) ;
	}

	// ????????ÅÒ??????Å~?????t?ÅÒ?O???Åò??????????ÅÒ???????
	if( ImageAfterFree )
	{
		DXFREE( Image ) ;
	}

	return -1 ;
}

// ?V?F?[?_?[?n?Åg?h???????n??
extern	int		Graphics_Hardware_D3D11_Shader_TerminateHandle_PF( SHADERHANDLEDATA *Shader )
{
	// ?V?F?[?_?[??ÅÒ???
	switch( Shader->ShaderType )
	{
	case DX_SHADERTYPE_VERTEX :
		if( Shader->PF->D3D11.VertexShader )
		{
			Direct3D11_Release_VertexShader( Shader->PF->D3D11.VertexShader ) ;
			Shader->PF->D3D11.VertexShader = NULL ;
		}
		break ;

	case DX_SHADERTYPE_GEOMETRY :
		if( Shader->PF->D3D11.GeometryShader )
		{
			Direct3D11_Release_GeometryShader( Shader->PF->D3D11.GeometryShader ) ;
			Shader->PF->D3D11.GeometryShader = NULL ;
		}
		break ;

	case DX_SHADERTYPE_PIXEL :
		if( Shader->PF->D3D11.PixelShader )
		{
			Direct3D11_Release_PixelShader( Shader->PF->D3D11.PixelShader ) ;
			Shader->PF->D3D11.PixelShader = NULL ;
		}
		break ;
	}

	// ?????I??
	return 0 ;
}

// ?g?p???????V?F?[?_?[???o?[?W?Åˆ?Åg????Åg?????( 0=?g??????  200=?V?F?[?_?[???f???Q?D?O???g?pÅÒ?Åh\  300=?V?F?[?_?[???f???R?D?O???g?pÅÒ?Åh\ )
extern	int		Graphics_Hardware_D3D11_Shader_GetValidShaderVersion_PF( void )
{
	switch( GD3D11.Setting.FeatureLevel )
	{
	case D_D3D_FEATURE_LEVEL_9_1 :
	case D_D3D_FEATURE_LEVEL_9_2 :
	case D_D3D_FEATURE_LEVEL_9_3 :
		return 200 ;

	case D_D3D_FEATURE_LEVEL_10_0 :
	case D_D3D_FEATURE_LEVEL_10_1 :
		return 400 ;

	case D_D3D_FEATURE_LEVEL_11_0 :
	case D_D3D_FEATURE_LEVEL_11_1 :
		return 500 ;
	}

	return 0 ;
}

